static void settings_flightmode_timer_event_cb(struct _lv_timer_t *timer)
{
    uint32_t result_type;

    result_type = (uint32_t )timer->user_data;
    if (settings_flightmode_timer) {
        lv_timer_del(settings_flightmode_timer);
        settings_flightmode_timer = NULL;
        if(settings_fp_flow_get_flightmode_status()){
            alv_am_win_jump_action(NULL,"setting_net_flight",NULL);
        }else{
            if(result_type==4){
                alv_am_app_exit_action_all();
                ts_sim_pin_param_init();
            }else{
                alv_am_win_jump_action(NULL,"setting_net_flight",NULL);
            }
        }
    }
}


void settings_flightmode_timer_start(void *p_param)
{

    if (settings_flightmode_timer == NULL) {
        settings_flightmode_timer = lv_timer_create(settings_flightmode_timer_event_cb,1500,p_param);

        }

}


